r="/Users/marcel.a.n.navarro/Dev/zimmermann-pwa"
echo "=== sites.js / overlay: id + SFCC site references ==="
grep -nE "id:|siteId|storefront-catalog|zimmermann-catalog|catalog" "$r/config/sites.js" "$r/config/sites.overlay.js" 2>/dev/null | head -60
echo
echo "=== count distinct site ids via node ==="
node -e '
try {
  const sites = require("'"$r"'/config/sites.js");
