} catch(e){ console.log("node load failed:", e.message); }'
echo
echo "=== any catalog id strings anywhere in repo (excl node_modules) ==="
grep -rInE "zimmermann-catalog|storefront-catalog|zimmermann-au-storefront" "$r" --include=*.js --include=*.ts --include=*.md --include=*.json -l 2>/dev/null | grep -v node_modules | head

